  "    ",
  "    def _relation_sequence_inverse(rng: np.random.Generator, v: int) -> list[int]:",
  "        \"\"\"Query gives OBJ and REL; answer SUB at end (next-token LM learns to emit SUB).\"\"\"",
  "        s0 = _num_special_reserve()",
  "        BOS, EOS = 1, 2",
  "        T_SUB, T_REL, T_OBJ = 7, 8, 9",
  "        T_Q = 10",
